<?php 	//add theme stylish	function gfct_stylish_theme(){		///set initial values		$options = get_option('gfct');		gfct_theme_color2('stylish','buttonhover');		gfct_theme_color2('stylish','facolor');		$button   = gfct_theme_color2('stylish','button');		$rgbac    = gfct_hex2RGB($options['stylish_orig']['background']);		$buttonhover = gfct_theme_color2('stylish','buttonhover');		$label = gfct_theme_color2('stylish','label');		$heading = gfct_theme_color2('stylish','heading');		$facolor = gfct_theme_color2('stylish','facolor');		///see if we need to replace default values and replace them		//can't do background because it is in rgb, function called		$rgba =  get_rgba('stylish');		$output='/*      Name : Stylish Theme*/.gfct_stylish .ginput_complex label {    color: '.$label.';}.gfct_stylish .button.gform_button:hover {    background: none repeat scroll 0 0 '. $buttonhover.';}.gfct_stylish .gfield_radio, .gfct_stylish .gfield_checkbox {    width: 56%;  margin-top:10px !important;}.gfct_stylish .gform_body {    width: 100%;}.gfct_stylish_wrapper h3.gform_title {    border-bottom: 1px solid '.$heading.';    line-height: 22px;    padding-bottom: 6px;    color:'.$heading.';}.gfct_stylish_wrapper li, .gfct_stylish_wrapper form li{  position:relative;  visibility:visible;}.gfct_stylish .button.gform_previous_button {    line-height: 22px !important;    margin-bottom: 5px !important;    width: 40% !important;}.gfct_stylish_wrapper h3.gf_progressbar_title {    color: white;    opacity: 1 !important;}.gfct_stylish_wrapper .button {    background: none repeat scroll 0 0 '.$button.';  border: 1px solid white;    color: #fff;    display: block;    line-height: 38px;    margin: 0 auto !important;    text-transform: uppercase;    width: 72%;}.gfct_stylish_wrapper .gf_progressbar_wrapper {    border-bottom: 1px solid #fff;}.gfct_stylish_wrapper .gfield_checkbox li label, .gfct_stylish_wrapper .gfield_radio li label, .gfct_stylish_wrapper ul.gfield_radio li input[type="radio"]:checked + label, .gfct_stylish_wrapper ul.gfield_checkbox li input[type="checkbox"]:checked + label {    color: '. $label .';}.gfct_stylish .gform_page_fields {    margin: 0 auto;    width: 70%;}.gfct_stylish_wrapper select, .gfct_stylish_wrapper select input[type="text"], .gfct_stylish_wrapper input[type="url"], .gfct_stylish_wrapper input[type="email"], .gfct_stylish_wrapper input[type="tel"], .gfct_stylish_wrapper input[type="number"], .gfct_stylish_wrapper input[type="password"] {    display: block;    line-height: 22px;    margin-bottom: 1px;    border:none;    border-radius: 2px;}.gfct_stylish .gfield_label {    color:'. $label .';    display: block;    margin: 0 auto;}.gfct_stylish_wrapper {    background: none repeat scroll 0 0 '. $rgba .';    border-radius: 10px;    margin: 40px auto;    padding: 10px 10%;    position: relative;}.gfct_stylish .gfct_fa_span i {    margin-top: 0.4em;    position: absolute;    color: '.$facolor.';}.gfct_stylish textarea {    margin: 1px 0;    padding-top: 6px;}.gfct_stylish_wrapper .left_label input.medium, .gfct_stylish_wrapper .left_label select.medium, .gfct_stylish_wrapper .right_label input.medium, .gfct_stylish_wrapper .right_label select.medium {    width: calc(72% - 8px);}.gfct_stylish_wrapper ul.gform_fields li.gfield {    padding-right: 0;}.gfct_stylish_wrapper .gform_footer {    min-height: 90px;}.gfct_stylish button, .gfct_stylish .button, .gfct_stylish input[type="button"], .gfct_stylish input[type="reset"], .gfct_stylish input[type="submit"] {    float: right;    margin-left: 4%;}.gfct_stylish_wrapper.gf_browser_chrome .gform_body {  padding:0 3%;  width:100%;}';		return $output;	}